DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'activity_type') THEN CREATE TYPE public.activity_type AS ENUM ('call','email','meeting','demo','follow_up','note','task'); ELSE IF NOT EXISTS (SELECT 1 FROM pg_enum WHERE enumtypid = 'public.activity_type'::regtype AND enumlabel = 'demo') THEN ALTER TYPE public.activity_type ADD VALUE 'demo'; END IF; IF NOT EXISTS (SELECT 1 FROM pg_enum WHERE enumtypid = 'public.activity_type'::regtype AND enumlabel = 'follow_up') THEN ALTER TYPE public.activity_type ADD VALUE 'follow_up'; END IF; END IF; END $$;